62	            rs.getLong("id"), rs.getLong("batch_id"), rs.getString("head_no"), rs.getString("status"),
63	            rs.getString("inspection_result"), rs.getString("judgment_category"),
64	            getNullableBoolean(rs, "high_temp"), rs.getString("circulation_area"),
65	            rs.getBoolean("inventory_marked"));
