81	            rs.getLong("id"), rs.getString("request_id"), rs.getString("endpoint"),
82	            rs.getString("fingerprint"), rs.getString("response_body"));
83	
84	    private static Boolean getNullableBoolean(ResultSet rs, String column) throws SQLException {
85	        boolean value = rs.getBoolean(column);
86	        return rs.wasNull() ? null : value;
87	    }
