91	    public void insertBatch(String batchNo, String species, String farmOrigin, int headCount,
92	                            String status, String declaredAt, String createdAt) {
93	        jdbc.update("INSERT INTO slaughter_batch(batch_no, species, farm_origin, head_count, status,"
