35	    @Test
36	    @DisplayName("宰前检疫自申报起6小时内有效，恰满6小时须重新申报")
37	    void quarantineWindowExactlySixHours() throws Exception {
38	        // 恰满前 1 秒：检疫有效
39	        declareOk("d-1", "B-6H-1", List.of("H1"));
40	        clock.set(TestClockConfig.T0.plus(SIX_HOURS).minusSeconds(1));
41	        preQuarantineOk("B-6H-1", "pq-1");
42	
43	        // 恰满 6 小时：检疫拒绝，须重新申报
44	        clock.set(TestClockConfig.T0);
45	        declareOk("d-2", "B-6H-2", List.of("H1"));
46	        clock.set(TestClockConfig.T0.plus(SIX_HOURS));
47	        postJson("/api/batches/B-6H-2/pre-quarantine", new PreQuarantineRequest("pq-2", "检疫员甲"))
48	                .andExpect(status().isUnprocessableEntity());
49	
50	        // 有效期恰满后批次仍未重新申报前，窗口外的重复申报按重新申报受理并重置窗口
51	        DeclareResponse redeclared = postOk("/api/batches/declare",
52	                new DeclareRequest("d-3", "B-6H-2", "PIG", "合成养殖场", List.of("H1")),
53	                DeclareResponse.class);
54	        assertEquals(TestClockConfig.T0.plus(SIX_HOURS).toString(), redeclared.declaredAt());
55	        assertEquals("DECLARED", redeclared.status());
56	
57	        // 重新申报后的新窗口内检疫通过
58	        preQuarantineOk("B-6H-2", "pq-3");
59	    }
