81	                item("H1", "QUALIFIED"), item("H2", "QUALIFIED"), item("H3", "QUALIFIED")))
82	                .andExpect(status().isConflict());
83	        assertEquals("PAUSED", getView("B-MISS").status());
84	
85	        // 暂停状态下补检漏检头只，随后判定放行
86	        inspectOk("B-MISS", "i-3", "H3");
87	        JudgmentResponse judged = postOk("/api/batches/B-MISS/judgments", judgmentRequest("j-2",
88	                item("H1", "QUALIFIED"), item("H2", "QUALIFIED"), item("H3", "QUALIFIED")),
